'use client';
const require_field = require("./field.cjs");
const require_field_affix = require("./field-affix.cjs");
const require_field_counter = require("./field-counter.cjs");
const require_field_description = require("./field-description.cjs");
//#region src/components/field/index.ts
/**
* Field component, used to wrap a form field.
*
* @example
* <Field>
*   <Label>Kort beskrivelse</Label>
*   <Field.Description>Beskrivelse</Field.Description>
*   <Input />
*   <ValidationMessage>Feilmelding</ValidationMessage>
* </Field>
*/
const FieldComponent = Object.assign(require_field.Field, {
	Description: require_field_description.FieldDescription,
	Affixes: require_field_affix.FieldAffixes,
	Affix: require_field_affix.FieldAffix,
	Counter: require_field_counter.FieldCounter
});
FieldComponent.Description.displayName = "Field.Description";
FieldComponent.Affixes.displayName = "Field.Affixes";
FieldComponent.Affix.displayName = "Field.Affix";
FieldComponent.Counter.displayName = "Field.Counter";
//#endregion
exports.Field = FieldComponent;
exports.FieldAffix = require_field_affix.FieldAffix;
exports.FieldAffixes = require_field_affix.FieldAffixes;
exports.FieldCounter = require_field_counter.FieldCounter;
exports.FieldDescription = require_field_description.FieldDescription;
